// Design tokens defined in Figma Variables can be exported (via plugin or Figma REST API)
// as JSON, then translated to a Flutter ThemeData.

class BrandTokens {
  // Colors
  static const Color primary = Color(0xFF1F3A5F);      // designer-approved
  static const Color surface = Color(0xFFF6F7F9);
  static const Color danger  = Color(0xFFC0392B);

  // Spacings (Figma variable: --space-2 → 8)
  static const double space1 = 4;
  static const double space2 = 8;
  static const double space3 = 12;
  static const double space4 = 16;
  static const double space6 = 24;

  // Type ramp (Figma variable: --font-body-md)
  static const TextStyle bodyMd = TextStyle(fontSize: 16, height: 24 / 16, letterSpacing: 0);
  static const TextStyle bodyLg = TextStyle(fontSize: 18, height: 28 / 18, letterSpacing: 0);
  static const TextStyle title  = TextStyle(fontSize: 24, height: 32 / 24, fontWeight: FontWeight.w600);
}

final theme = ThemeData(
  colorScheme: ColorScheme.light(
    primary: BrandTokens.primary,
    surface: BrandTokens.surface,
    error: BrandTokens.danger,
  ),
  textTheme: TextTheme(
    bodyMedium: BrandTokens.bodyMd,
    titleLarge: BrandTokens.title,
  ),
);

// Tools like `figma_to_flutter`, `Figma Tokens`, or Codemagic's Figma exporter
// automate this JSON → Dart generation.
